import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"微信支付（完整配置手册）","description":"微信支付（完整配置手册）：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/wechat-pay.md","filePath":"features/wechat-pay.md","lastUpdated":1785051348000}'),n={name:"features/wechat-pay.md"};function s(o,t,l,i,h,p){return r(),d("div",null,[...t[0]||(t[0]=[e(`<h1 id="微信支付-完整配置手册" tabindex="-1">微信支付（完整配置手册） <a class="header-anchor" href="#微信支付-完整配置手册" aria-label="Permalink to &quot;微信支付（完整配置手册）&quot;">​</a></h1><p>本篇从 <strong>微信商户平台</strong> 到 <strong>灵萌管理后台</strong> 到 <strong>客户端验收</strong>，逐步说明如何开通微信支付、配置回调、处理提现打款。</p><p><strong>后台入口：</strong> <strong>系统设置 → 系统配置 → 微信支付</strong> Tab</p><div class="warning custom-block"><p class="custom-block-title">前置条件</p><ul><li>站点 <strong>HTTPS</strong> 已配置，域名与 <strong>网站信息</strong> / 初始化向导 <strong>网站地址</strong> 一致</li><li><strong>支付</strong> 模块已在 <strong>系统设置 → 我的模块</strong> 中开通</li><li>小程序 AppID 已在商户平台与商户号 <strong>绑定</strong></li></ul></div><hr><h2 id="一、整体流程概览" tabindex="-1">一、整体流程概览 <a class="header-anchor" href="#一、整体流程概览" aria-label="Permalink to &quot;一、整体流程概览&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 注册微信支付商户号（企业资质）</span></span>
<span class="line"><span>2. 商户平台绑定小程序 AppID</span></span>
<span class="line"><span>3. 申请 API 证书、设置 APIv3 密钥</span></span>
<span class="line"><span>4. 配置支付通知 URL（回调）</span></span>
<span class="line"><span>5. 灵萌后台填写商户号、密钥、证书</span></span>
<span class="line"><span>6. 区域/业务侧开启付费能力</span></span>
<span class="line"><span>7. 0.01 元测试单验收</span></span>
<span class="line"><span>8. （可选）申请商家转账 → 填转账场景 ID → 提现自动打款</span></span></code></pre></div><hr><h2 id="二、微信商户平台操作-逐步" tabindex="-1">二、微信商户平台操作（逐步） <a class="header-anchor" href="#二、微信商户平台操作-逐步" aria-label="Permalink to &quot;二、微信商户平台操作（逐步）&quot;">​</a></h2><p>登录 <a href="https://pay.weixin.qq.com" target="_blank" rel="noreferrer">微信支付商户平台</a></p><h3 id="_2-1-确认商户号" tabindex="-1">2.1 确认商户号 <a class="header-anchor" href="#_2-1-确认商户号" aria-label="Permalink to &quot;2.1 确认商户号&quot;">​</a></h3><p>路径：<strong>账户中心 → 商户信息</strong></p><p>记下 <strong>商户号</strong>（10 位数字），填入灵萌后台 <strong>商户号</strong> 字段。</p><h3 id="_2-2-绑定-appid" tabindex="-1">2.2 绑定 AppID <a class="header-anchor" href="#_2-2-绑定-appid" aria-label="Permalink to &quot;2.2 绑定 AppID&quot;">​</a></h3><p>路径：<strong>产品中心 → AppID账号管理 → 关联AppID</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>操作</th></tr></thead><tbody><tr><td>1</td><td>点击 <strong>关联 AppID</strong></td></tr><tr><td>2</td><td>填写小程序 <strong>AppID</strong>（与 <strong>系统配置 → 微信小程序</strong> 一致）</td></tr><tr><td>3</td><td>小程序管理员扫码确认</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">未绑定则无法支付</p><p>AppID 与商户号主体可以不同，但必须在此完成关联。</p></div><h3 id="_2-3-设置-apiv3-密钥" tabindex="-1">2.3 设置 APIv3 密钥 <a class="header-anchor" href="#_2-3-设置-apiv3-密钥" aria-label="Permalink to &quot;2.3 设置 APIv3 密钥&quot;">​</a></h3><p>路径：<strong>账户中心 → API安全 → 设置APIv3密钥</strong></p><ul><li>设置 32 位密钥，<strong>妥善保存</strong></li><li>填入灵萌 <strong>支付密钥</strong> 字段（页面提示 v2/v3，按实际接入填 APIv3 密钥）</li></ul><h3 id="_2-4-申请-api-证书" tabindex="-1">2.4 申请 API 证书 <a class="header-anchor" href="#_2-4-申请-api-证书" aria-label="Permalink to &quot;2.4 申请 API 证书&quot;">​</a></h3><p>路径：<strong>账户中心 → API安全 → 申请API证书</strong></p><p>下载后得到：</p><table tabindex="0"><thead><tr><th>文件</th><th>对应灵萌字段</th></tr></thead><tbody><tr><td><code>apiclient_cert.pem</code></td><td><strong>CERT 证书</strong>（完整粘贴含 BEGIN/END 行）</td></tr><tr><td><code>apiclient_key.pem</code></td><td><strong>KEY 密钥</strong>（商户私钥）</td></tr></tbody></table><p>同时记录 <strong>证书序列号</strong> → 填入 <strong>v3 证书序列号</strong>。</p><h3 id="_2-5-设置支付回调-url" tabindex="-1">2.5 设置支付回调 URL <a class="header-anchor" href="#_2-5-设置支付回调-url" aria-label="Permalink to &quot;2.5 设置支付回调 URL&quot;">​</a></h3><p>路径：<strong>产品中心 → 开发配置 → 支付配置</strong></p><p>找到 <strong>Native支付 / JSAPI支付</strong> 等已开通产品的 <strong>支付通知URL</strong>，填写：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://你的域名/api/payment/wx-notify</span></span></code></pre></div><table tabindex="0"><thead><tr><th>注意项</th><th>说明</th></tr></thead><tbody><tr><td>必须 HTTPS</td><td>微信只回调 443</td></tr><tr><td>路径大小写</td><td>必须是 <code>/api/payment/wx-notify</code></td></tr><tr><td>无多余斜杠</td><td>域名后不要双斜杠</td></tr><tr><td>外网可达</td><td>微信服务器能 POST 到该地址</td></tr></tbody></table><p><strong>如何自测回调可达：</strong></p><ul><li>用浏览器访问会 405/404 正常（须接受 POST）</li><li>看 Nginx 是否把 <code>/api/</code> 反代到 Go 服务</li><li><strong>勿</strong> 对 <code>/api/payment/wx-notify</code> 做 CDN 缓存</li></ul><h3 id="_2-6-开通「商家转账到零钱」-提现自动打款-可选" tabindex="-1">2.6 开通「商家转账到零钱」（提现自动打款，可选） <a class="header-anchor" href="#_2-6-开通「商家转账到零钱」-提现自动打款-可选" aria-label="Permalink to &quot;2.6 开通「商家转账到零钱」（提现自动打款，可选）&quot;">​</a></h3><p>路径：<strong>产品中心 → 商家转账</strong> → 按指引开通</p><p>开通后申请 <strong>转账场景</strong>，获得 <strong>场景 ID</strong> → 填入灵萌 <strong>转账场景 ID</strong>。</p><p>未开通时：用户提现只能 <strong>人工打款</strong> 或在 <strong>财务管理 → 提现处理</strong> 手动处理。</p><hr><h2 id="三、灵萌管理后台填写-逐字段" tabindex="-1">三、灵萌管理后台填写（逐字段） <a class="header-anchor" href="#三、灵萌管理后台填写-逐字段" aria-label="Permalink to &quot;三、灵萌管理后台填写（逐字段）&quot;">​</a></h2><p>路径：<strong>系统设置 → 系统配置 → 微信支付</strong></p><h3 id="_3-1-基本信息区" tabindex="-1">3.1 基本信息区 <a class="header-anchor" href="#_3-1-基本信息区" aria-label="Permalink to &quot;3.1 基本信息区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>后台字段</th><th>填什么</th><th>必填</th><th>常见错误</th></tr></thead><tbody><tr><td><strong>商户号</strong></td><td>商户平台 10 位商户号</td><td>✅</td><td>填成 AppID</td></tr><tr><td><strong>支付密钥</strong></td><td>APIv3 密钥</td><td>✅</td><td>用错 v2 密钥；多空格</td></tr><tr><td><strong>v3 证书序列号</strong></td><td>证书管理页序列号</td><td>✅</td><td>证书更新后未改</td></tr><tr><td><strong>支付公钥 ID</strong></td><td>平台公钥 ID</td><td>视接入</td><td>—</td></tr><tr><td><strong>转账场景 ID</strong></td><td>商家转账场景 ID</td><td>自动打款必填</td><td>未开通转账就填</td></tr></tbody></table><h3 id="_3-2-证书内容区" tabindex="-1">3.2 证书内容区 <a class="header-anchor" href="#_3-2-证书内容区" aria-label="Permalink to &quot;3.2 证书内容区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>后台字段</th><th>填什么</th></tr></thead><tbody><tr><td><strong>CERT 证书</strong></td><td>完整 <code>apiclient_cert.pem</code> 内容</td></tr><tr><td><strong>KEY 密钥</strong></td><td>完整 <code>apiclient_key.pem</code> 私钥</td></tr><tr><td><strong>支付公钥</strong></td><td>微信支付平台公钥 PEM</td></tr></tbody></table><p>粘贴时注意：</p><ul><li>保留 <code>-----BEGIN ...-----</code> 和 <code>-----END ...-----</code></li><li>不要多空行或缺行</li><li>私钥 <strong>切勿</strong> 泄露到公开仓库</li></ul><p>填写完成后 <strong>保存</strong> 该 Tab。</p><hr><h2 id="四、与小程序配置的关联" tabindex="-1">四、与小程序配置的关联 <a class="header-anchor" href="#四、与小程序配置的关联" aria-label="Permalink to &quot;四、与小程序配置的关联&quot;">​</a></h2><p>微信支付 <strong>不能单独工作</strong>，须与小程序配置一致：</p><table tabindex="0"><thead><tr><th>配置位置</th><th>字段</th><th>要求</th></tr></thead><tbody><tr><td><strong>系统配置 → 微信小程序</strong></td><td>AppID / Secret</td><td>Token 测试通过</td></tr><tr><td><strong>微信商户平台</strong></td><td>AppID 绑定</td><td>已关联同一 AppID</td></tr><tr><td><strong>小程序后台</strong></td><td>服务器域名</td><td>request 合法域名含 API 域名</td></tr></tbody></table><p>用户 <strong>微信小程序登录</strong> 与支付用的是 <strong>同一小程序 AppID</strong>。</p><hr><h2 id="五、哪些业务会用到微信支付" tabindex="-1">五、哪些业务会用到微信支付 <a class="header-anchor" href="#五、哪些业务会用到微信支付" aria-label="Permalink to &quot;五、哪些业务会用到微信支付&quot;">​</a></h2><p>配置完成后，以下场景会调起微信支付（须对应 <strong>功能/区域</strong> 也已开启）：</p><table tabindex="0"><thead><tr><th>业务</th><th>典型入口</th><th>后台相关</th></tr></thead><tbody><tr><td>商城/订单</td><td>商品下单</td><td>商户配置</td></tr><tr><td>红包</td><td>私信/群聊发红包</td><td><a href="/features/payment">支付</a> + 余额</td></tr><tr><td>转账</td><td>用户间转账</td><td>同上</td></tr><tr><td>闲置交易</td><td>闲置帖成交</td><td>区域闲置配置</td></tr><tr><td>外卖</td><td>外卖订单</td><td><a href="/features/takeaway">外卖配置</a></td></tr><tr><td>跑腿</td><td>服务表单提交</td><td><a href="/features/errand">跑腿</a></td></tr><tr><td>用户充值</td><td>钱包充值</td><td>财务管理</td></tr><tr><td>提现打款</td><td>提现到微信零钱</td><td>转账场景 ID + 提现审核</td></tr></tbody></table><hr><h2 id="六、提现与打款" tabindex="-1">六、提现与打款 <a class="header-anchor" href="#六、提现与打款" aria-label="Permalink to &quot;六、提现与打款&quot;">​</a></h2><h3 id="_6-1-用户提现流程" tabindex="-1">6.1 用户提现流程 <a class="header-anchor" href="#_6-1-用户提现流程" aria-label="Permalink to &quot;6.1 用户提现流程&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 App 申请提现</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>财务管理 → 提现处理（待审核）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>管理员审核通过</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>已配置商家转账 → 自动打款到微信零钱</span></span>
<span class="line"><span>未配置 → 人工线下转账</span></span></code></pre></div><h3 id="_6-2-后台菜单" tabindex="-1">6.2 后台菜单 <a class="header-anchor" href="#_6-2-后台菜单" aria-label="Permalink to &quot;6.2 后台菜单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>财务管理 → 提现处理</strong></td><td>审核通过/拒绝</td></tr><tr><td><strong>财务管理 → 资金交易</strong></td><td>支付、退款、转账流水</td></tr><tr><td><strong>财务管理 → 余额流水</strong></td><td>用户余额变动</td></tr></tbody></table><h3 id="_6-3-打款失败常见原因" tabindex="-1">6.3 打款失败常见原因 <a class="header-anchor" href="#_6-3-打款失败常见原因" aria-label="Permalink to &quot;6.3 打款失败常见原因&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>未填转账场景 ID</td><td>商户平台申请场景并填入后台</td></tr><tr><td>证书/密钥错误</td><td>重新下载证书并更新</td></tr><tr><td>用户未实名 / 未绑微信</td><td>用户侧完成绑定</td></tr><tr><td>商户运营账户余额不足</td><td>商户平台充值</td></tr></tbody></table><hr><h2 id="七、完整验收-checklist" tabindex="-1">七、完整验收 checklist <a class="header-anchor" href="#七、完整验收-checklist" aria-label="Permalink to &quot;七、完整验收 checklist&quot;">​</a></h2><h3 id="_7-1-配置阶段" tabindex="-1">7.1 配置阶段 <a class="header-anchor" href="#_7-1-配置阶段" aria-label="Permalink to &quot;7.1 配置阶段&quot;">​</a></h3><ul><li>[ ] 商户号与 AppID 已绑定</li><li>[ ] APIv3 密钥、证书序列号、CERT、KEY 已填入并 <strong>保存</strong></li><li>[ ] 回调 URL 已在商户平台配置为 <code>https://域名/api/payment/wx-notify</code></li><li>[ ] 小程序 <strong>系统配置 → 微信小程序</strong> Token 成功</li></ul><h3 id="_7-2-支付测试" tabindex="-1">7.2 支付测试 <a class="header-anchor" href="#_7-2-支付测试" aria-label="Permalink to &quot;7.2 支付测试&quot;">​</a></h3><ul><li>[ ] 小程序发起 <strong>0.01 元</strong> 测试支付</li><li>[ ] 支付成功，订单状态变为已支付</li><li>[ ] <strong>财务管理 → 资金交易</strong> 有 SUCCESS 记录</li><li>[ ] 商户平台 <strong>交易中心</strong> 有对应订单</li></ul><h3 id="_7-3-回调测试" tabindex="-1">7.3 回调测试 <a class="header-anchor" href="#_7-3-回调测试" aria-label="Permalink to &quot;7.3 回调测试&quot;">​</a></h3><ul><li>[ ] 支付后 <strong>5 秒内</strong> 订单状态更新（非长时间待支付）</li><li>[ ] 服务器日志无持续「验签失败」</li><li>[ ] Nginx 未对 POST 回调返回 301/302 到错误页</li></ul><h3 id="_7-4-提现测试-若启用" tabindex="-1">7.4 提现测试（若启用） <a class="header-anchor" href="#_7-4-提现测试-若启用" aria-label="Permalink to &quot;7.4 提现测试（若启用）&quot;">​</a></h3><ul><li>[ ] 转账场景 ID 已填</li><li>[ ] 测试用户小额提现 → 审核通过 → 微信零钱到账</li></ul><hr><h2 id="八、故障排查表" tabindex="-1">八、故障排查表 <a class="header-anchor" href="#八、故障排查表" aria-label="Permalink to &quot;八、故障排查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>排查顺序</th></tr></thead><tbody><tr><td><strong>支付页提示未配置</strong></td><td>支付模块是否开通 → 微信支付 Tab 是否保存 → 商户号是否填</td></tr><tr><td><strong>调起支付失败</strong></td><td>AppID 绑定 → 小程序与后台 AppID 一致 → 用户 openid 有效</td></tr><tr><td><strong>已付款仍待支付</strong></td><td>回调 URL → 证书/公钥 → Nginx 反代 → 防火墙</td></tr><tr><td><strong>验签失败</strong></td><td>KEY/CERT 是否配对 → 平台公钥是否最新 → 序列号是否匹配</td></tr><tr><td><strong>退款失败</strong></td><td>证书权限 → 订单状态 → 商户平台退款记录</td></tr><tr><td><strong>提现不到账</strong></td><td>转账场景 ID → 审核是否通过 → 商户转账产品是否开通</td></tr></tbody></table><h3 id="日志与监控位置" tabindex="-1">日志与监控位置 <a class="header-anchor" href="#日志与监控位置" aria-label="Permalink to &quot;日志与监控位置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>位置</th><th>看什么</th></tr></thead><tbody><tr><td><strong>财务管理 → 资金交易</strong></td><td>订单号、状态、金额</td></tr><tr><td><strong>系统监控 → 系统状态</strong></td><td>支付链路健康</td></tr><tr><td><strong>系统监控 → 对账中心</strong></td><td>异常对账（有权限时）</td></tr><tr><td>服务器日志</td><td><code>wx-notify</code>、验签、回调 body</td></tr></tbody></table><hr><h2 id="九、与支付宝并存" tabindex="-1">九、与支付宝并存 <a class="header-anchor" href="#九、与支付宝并存" aria-label="Permalink to &quot;九、与支付宝并存&quot;">​</a></h2><p>灵萌支持 <strong>微信 + 支付宝</strong> 同时配置，用户支付时可选择渠道。</p><table tabindex="0"><thead><tr><th>项目</th><th>微信</th><th>支付宝</th></tr></thead><tbody><tr><td>后台 Tab</td><td>微信支付</td><td>支付宝</td></tr><tr><td>回调</td><td><code>/api/payment/wx-notify</code></td><td><code>/api/payment/alipay-notify</code></td></tr><tr><td>手册</td><td>本文</td><td><a href="/features/payment#2-支付宝">支付与提现</a></td></tr></tbody></table><hr><h2 id="十、生产环境安全建议" tabindex="-1">十、生产环境安全建议 <a class="header-anchor" href="#十、生产环境安全建议" aria-label="Permalink to &quot;十、生产环境安全建议&quot;">​</a></h2><ol><li>商户 API 证书仅保存在服务器，不要通过 IM 传播</li><li>定期在商户平台 <strong>轮换 APIv3 密钥</strong> 并同步更新后台</li><li>回调 URL 仅允许微信 IP 段访问（可选 WAF 规则）</li><li>提现审核与打款权限分离，避免单人可操作全流程</li></ol><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/wechat">微信登录与公众号</a></li><li><a href="/features/payment">支付与提现总览</a></li><li><a href="/config/system-settings#tab-3微信支付">系统配置 — 微信支付 Tab</a></li><li><a href="/features/message">私信红包转账</a></li><li><a href="/ops/checklist">上线检查清单</a></li></ul>`,88)])])}const b=a(n,[["render",s]]);export{c as __pageData,b as default};
